package com.artforyou.store.entity;
import jakarta.persistence.*;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String collection; @Column(nullable=false) private String category; @Column(nullable=false) private String name; @Column(nullable=false) private Integer price; @Column(columnDefinition="json") private String images="[]"; @Column(columnDefinition="text") private String description=""; private boolean active=true; @Column(name="sort_order") private int sortOrder; public Long getId(){return id;} public String getCollection(){return collection;} public String getCategory(){return category;} public String getName(){return name;} public Integer getPrice(){return price;} public String getImages(){return images;} public String getDescription(){return description;} public boolean isActive(){return active;} public int getSortOrder(){return sortOrder;} public void setCollection(String v){collection=v;} public void setCategory(String v){category=v;} public void setName(String v){name=v;} public void setPrice(Integer v){price=v;} public void setImages(String v){images=v;} public void setDescription(String v){description=v;} public void setActive(boolean v){active=v;} public void setSortOrder(int v){sortOrder=v;} }
